{
FLOAT fStretch  = (m_vStretch  (1) + m_vStretch  (2) + m_vStretch  (3)) / 3.0f;
Particles_DisappearDust  (this  , fStretch  , m_tmSpawn );
}
if(m_betType  == BET_DUST_FALL )
{
Particles_DustFall  (this  , m_tmSpawn  , m_vStretch );
}
